/**
 * Shiny palettes (added 2026-10-26, spine §3.7a): a shiny wears its family's own hue / saturation / lightness triple
 * in place of its variant's, through the same four per-object sprite values (render `paletteFor`), so no pixel is
 * re-baked. The defaults are derived from each family's thumbnails (`shinyDerived.ts`, generated by
 * `pnpm --filter @ewa/sprite-pipeline shiny`); `SHINY_TUNING` replaces a default by species id or by family root.
 */
import type { VariantPalette } from '../types';
import { evolutionRoot } from './arena';
import { SHINY_DERIVED } from './shinyDerived';

/** A family with no derived entry yet (a species added before the derive script was re-run). */
export const SHINY_FALLBACK: VariantPalette = { hue: 160, saturation: 1.1, lightness: 1 };

/**
 * The hand-tuned pass over the derived defaults, keyed by family root (the whole line) or by one species id (wins
 * over its root). Hue in degrees (the shader's rotation about the grey axis), saturation and lightness multipliers.
 */
export const SHINY_TUNING: Readonly<Record<string, VariantPalette>> = {
  // white / pale bodies: a hue shift barely shows, so their faint tints are pushed instead
  glimp: { hue: 150, saturation: 2.2, lightness: 0.95 },
  slushpup: { hue: -48, saturation: 2.2, lightness: 0.95 },
  seedrift: { hue: -116, saturation: 2, lightness: 0.9 },
  shardling: { hue: -55, saturation: 2, lightness: 0.95 },
  fibrostis: { hue: 72, saturation: 2.2, lightness: 0.9 },
  // near-black bodies: lighter, with the accents carried further
  umbrit: { hue: -59, saturation: 1.8, lightness: 1.45 },
  castlemaw: { hue: -75, saturation: 1.8, lightness: 1.4 },
  noxmyth: { hue: 164, saturation: 1.6, lightness: 1.35 },
  hollowmane: { hue: 174, saturation: 1.6, lightness: 1.2 },
  // derived shifts that landed on a drab olive / too near the original
  zaptus: { hue: 65, saturation: 1.05, lightness: 1 },
  scalewisp: { hue: 140, saturation: 1.05, lightness: 1 },
  nettlewisp: { hue: 160, saturation: 1.05, lightness: 1 },
};

export function shinyPaletteOf(speciesId: string): VariantPalette {
  const root = evolutionRoot(speciesId);
  return SHINY_TUNING[speciesId] ?? SHINY_TUNING[root] ?? SHINY_DERIVED[root] ?? SHINY_FALLBACK;
}
